# Result latency is the issue-to-dependent-issue distance (FU latency + 10).
add a0, a1, a2
add a3, a0, a0
lw a4, 0(a5)
add a6, a4, a4
csrr t0, mhartid
add t1, t0, t0
amoadd.w t2, t3, (t4)
add t5, t2, t2
amocas.w s0, s1, (s2)
add s3, s0, s0
amocas.d.aqrl s4, s5, (s6)
add s7, s4, s4

# MUL/DIV/REM share the MDU, which accepts one op per cycle.
mul a0, a1, a2
div a3, a1, a2
rem a4, a1, a2
mul a5, a0, a0

# FP div/sqrt share the fully pipelined FPU with the other FP ops.
fadd.s a6, a1, a2
fdiv.s a7, a1, a2
fsqrt.s t0, a1
fmul.d t1, a1, a2
fadd.s t2, a6, a6

